# Mobility stores a translation per locale for the attributes a model declares
# with `translates`. Generated by `rails generate mobility:install
# --without_tables`, then trimmed to the plugins this app actually uses.
#
# The available/default locales themselves are not set here: Mobility reads
# them from `Rails.application.config.i18n` (see config/application.rb), so
# there is only one place to change them.
Mobility.configure do
  plugins do
    # Default backend for `translates` calls that don't name one. Every
    # translated plain-text column in this app is a Postgres jsonb column named
    # after the attribute (`posts.title` holds `{"en" => ..., "de" => ...}`),
    # which is what the :jsonb backend expects with no column prefix/suffix.
    # Rich text opts out per-attribute with `backend: :action_text`.
    backend :jsonb

    active_record

    # Reader/writer methods for each translated attribute (`post.title`).
    reader
    writer

    # `post.title_backend`, used by tests to assert which backend is in play.
    backend_reader

    # Adds the `.i18n` scope, which rewrites `where(title: "x")` into a query
    # against the current locale's key inside the jsonb column. Plain
    # `where(title: "x")` would compare a jsonb column to a string and is
    # exactly the trap the slug uniqueness validation has to avoid.
    query

    # Caches backend reads/writes for the lifetime of the instance.
    cache

    # Blank strings in, nil out -- so a locale left empty in the admin reads as
    # "untranslated" and falls back, rather than rendering an empty string.
    presence

    # Off by default: `fallbacks({})` keeps the plugin (so a per-read
    # `fallback:` override still works, and the `presence`/`cache` plugins
    # above it in the stack still apply) but gives it no locales to fall
    # through to, so a plain reader with no explicit `locale:`/`fallback:`
    # returns the literal value for the ambient locale -- nil if that locale
    # has nothing, never another locale's text. (`fallbacks false` would drop
    # the plugin's reader override entirely, taking the `fallback:` kwarg with
    # it.) Public views never see this literal value directly: they read
    # through `Locales.read` (app/models/locales.rb), which walks
    # `Locales.fallback_chain` itself. Admin and MCP want the literal value on
    # purpose, so an empty translation shows as empty rather than borrowing
    # another locale's text.
    fallbacks({})

    # Defines `title_en` / `title_de=` / ... for every available locale. The
    # Avo resource edits one locale per tab through these, and unlike the plain
    # reader they deliberately do *not* fall back -- editing the German tab has
    # to show German or nothing, never the English text.
    locale_accessors
  end
end
